--
-- Name: extract_product_color(text); Type: FUNCTION; Schema: tnbike; Owner: -
--

CREATE FUNCTION tnbike.extract_product_color(product_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
    WHEN product_name IS NULL OR BTRIM(product_name) = '' THEN 'Không xác định'

    -- Màu chính đứng trước thông tin tem
    WHEN product_name ~* 'trắng\s*\(?\s*tem' THEN 'Trắng'
    WHEN product_name ~* 'đen\s*\(?\s*tem' THEN 'Đen'
    WHEN product_name ~* 'xanh\s*\(?\s*tem' THEN 'Xanh'
    WHEN product_name ~* 'ghi\s*\(?\s*tem' THEN 'Ghi'

    -- Màu ghép, phải ưu tiên trước màu đơn
    WHEN product_name ILIKE '%hồng%dạ%quang%' THEN 'Hồng dạ quang'
    WHEN product_name ILIKE '%tím%dạ%quang%' THEN 'Tím dạ quang'
    WHEN product_name ILIKE '%xanh%da%trời%' THEN 'Xanh da trời'
    WHEN product_name ILIKE '%vàng%cánh%gián%' THEN 'Vàng cánh gián'
    WHEN product_name ILIKE '%vàng%chanh%' THEN 'Vàng chanh'
    WHEN product_name ILIKE '%xanh%nước%biển%' THEN 'Xanh nước biển'
    WHEN product_name ILIKE '%xanh%dương%' THEN 'Xanh dương'
    WHEN product_name ILIKE '%xanh%santorini%' THEN 'Xanh Santorini'
    WHEN product_name ILIKE '%pastel%xanh%' THEN 'Pastel Xanh'
    WHEN product_name ILIKE '%xanh%mint%' THEN 'Xanh mint'
    WHEN product_name ILIKE '%xanh%ngọc%' THEN 'Xanh ngọc'
    WHEN product_name ILIKE '%xanh%lá%' THEN 'Xanh lá'
    WHEN product_name ILIKE '%xanh%rêu%' THEN 'Xanh rêu'
    WHEN product_name ILIKE '%xanh%tím%' THEN 'Xanh Tím'
    WHEN product_name ILIKE '%đỏ%tươi%' THEN 'Đỏ tươi'
    WHEN product_name ILIKE '%đỏ%đun%' THEN 'Đỏ đun'
    WHEN product_name ILIKE '%đỏ%đậm%' THEN 'Đỏ đậm'
    WHEN product_name ILIKE '%café%nâu%' OR product_name ILIKE '%cafe%nau%' THEN 'Café/nâu'

    -- Tên có tem/theme nhưng vẫn có màu chính
    WHEN product_name ILIKE '%xanh%superman%' THEN 'Xanh'
    WHEN product_name ILIKE '%đỏ%wonderwoman%' THEN 'Đỏ'
    WHEN product_name ILIKE '%đen%bat%man%' THEN 'Đen'
    WHEN product_name ILIKE '%superman%dc%xanh%' THEN 'Xanh'

    -- Màu đơn
    WHEN product_name ILIKE '%trắng%' THEN 'Trắng'
    WHEN product_name ILIKE '%đen%' THEN 'Đen'
    WHEN product_name ILIKE '%hồng%' THEN 'Hồng'
    WHEN product_name ILIKE '%đỏ%' THEN 'Đỏ'
    WHEN product_name ILIKE '%xanh%' THEN 'Xanh'
    WHEN product_name ILIKE '%tím%' THEN 'Tím'
    WHEN product_name ILIKE '%vàng%' THEN 'Vàng'
    WHEN product_name ILIKE '%cam%' AND product_name NOT ILIKE '%tem%cam%' THEN 'Cam'
    WHEN product_name ILIKE '%ghi%' THEN 'Ghi'
    WHEN product_name ILIKE '%kem%' THEN 'Kem'
    WHEN product_name ILIKE '%coban%' THEN 'Coban'
    WHEN product_name ILIKE '%ngọc%' THEN 'Ngọc'
    WHEN product_name ILIKE '%nâu%' THEN 'Nâu'
    WHEN product_name ILIKE '%rêu%' THEN 'Rêu'
    WHEN product_name ILIKE '%be%' THEN 'Be'

    ELSE 'Không xác định'
END
$$;


--
-- Name: fn_update_order_totals(); Type: FUNCTION; Schema: tnbike; Owner: -
--

CREATE FUNCTION tnbike.fn_update_order_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order_id INT;
BEGIN
    v_order_id := COALESCE(NEW.order_id, OLD.order_id);

    UPDATE tnbike.sales_order
    SET
        total_amount = (
            SELECT COALESCE(SUM(line_total), 0)
            FROM tnbike.order_line
            WHERE order_id = v_order_id
        ),
        total_quantity = (
            SELECT COALESCE(SUM(quantity), 0)::INTEGER
            FROM tnbike.order_line
            WHERE order_id = v_order_id
        ),
        line_count = (
            SELECT COUNT(*)
            FROM tnbike.order_line
            WHERE order_id = v_order_id
        )
    WHERE order_id = v_order_id;

    RETURN COALESCE(NEW, OLD);
END;
$$;


