-- Name: FUNCTION fn_update_order_totals(); Type: COMMENT; Schema: tnbike; Owner: -
--

COMMENT ON FUNCTION tnbike.fn_update_order_totals() IS 'Tự động cập nhật total_amount, total_quantity, line_count trên sales_order sau khi thay đổi order_line';


