CREATE TABLE tnbike.stg_orders_raw (
    stg_order_id bigint NOT NULL,
    message_id text,
    file_name text,
    from_address text,
    subject text,
    received_at timestamp with time zone,
    attachment_name text,
    email_so_number text,
    pdf_so_number text,
    email_order_date date,
    pdf_order_date date,
    email_customer_name text,
    pdf_customer_name text,
    email_tax_id text,
    pdf_tax_id text,
    email_address text,
    pdf_address text,
    email_phone text,
    email_total_quantity numeric,
    pdf_total_quantity numeric,
    email_total_amount numeric,
    pdf_total_amount numeric,
    loaded_at timestamp with time zone DEFAULT now()
);


--
-- Name: stg_orders_raw_stg_order_id_seq; Type: SEQUENCE; Schema: tnbike; Owner: -
--

CREATE SEQUENCE tnbike.stg_orders_raw_stg_order_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: stg_orders_raw_stg_order_id_seq; Type: SEQUENCE OWNED BY; Schema: tnbike; Owner: -
--

ALTER SEQUENCE tnbike.stg_orders_raw_stg_order_id_seq OWNED BY tnbike.stg_orders_raw.stg_order_id;


--
-- Name: v_customer_activity; Type: VIEW; Schema: tnbike; Owner: -
--

CREATE VIEW tnbike.v_customer_activity AS
 SELECT c.customer_code,
    c.customer_name,
    c.province_id,
    p.province_name,
    p.region,
    count(DISTINCT so.so_number) AS total_orders,
    sum(ol.line_total) AS total_revenue,
    min(so.order_date) AS first_order_date,
    max(so.order_date) AS last_order_date,
    (CURRENT_DATE - max(so.order_date)) AS days_since_last_order
   FROM (((tnbike.customer c
     LEFT JOIN tnbike.sales_order so ON (((so.customer_code)::text = (c.customer_code)::text)))
     LEFT JOIN tnbike.order_line ol ON ((ol.order_id = so.order_id)))
     LEFT JOIN tnbike.province p ON ((p.province_id = c.province_id)))
  GROUP BY c.customer_code, c.customer_name, c.province_id, p.province_name, p.region;


--
-- Name: VIEW v_customer_activity; Type: COMMENT; Schema: tnbike; Owner: -
--

COMMENT ON VIEW tnbike.v_customer_activity IS 'Hoạt động tổng hợp của từng khách hàng — phát hiện churn signal';


--
-- Name: v_customer_period; Type: VIEW; Schema: tnbike; Owner: -
--

CREATE VIEW tnbike.v_customer_period AS
 SELECT fiscal_year,
    fiscal_quarter,
    customer_code,
    customer_name,
    province_name,
    region,
    count(DISTINCT so_number) AS order_count,
    sum(quantity) AS total_qty,
    sum(line_total) AS total_revenue,
    max(order_date) AS last_order_date,
    min(order_date) AS first_order_date
   FROM tnbike.fact_sales
  GROUP BY fiscal_year, fiscal_quarter, customer_code, customer_name, province_name, region;


--
-- Name: VIEW v_customer_period; Type: COMMENT; Schema: tnbike; Owner: -
--

COMMENT ON VIEW tnbike.v_customer_period IS 'Tổng hợp khách hàng theo quý — nền tảng cho RFM và churn detection';


--
-- Name: v_fact_sales_dashboard; Type: VIEW; Schema: tnbike; Owner: -
--

CREATE VIEW tnbike.v_fact_sales_dashboard AS
 SELECT fs.fact_id,
    fs.order_date,
    fs.fiscal_year,
    fs.fiscal_quarter,
    fs.fiscal_month,
    fs.week_of_year,
    fs.so_number,
    fs.order_id,
    fs.line_id,
    fs.customer_code,
    fs.customer_name,
    fs.province_id,
    fs.province_name,
    fs.region,
    fs.product_code,
    fs.product_name,
    fs.color,
    fs.line_id_fk,
    fs.line_name,
    fs.group_code,
    fs.group_name,
    fs.quantity,
    fs.unit_price,
    fs.line_total,
    (fs.customer_code)::text AS customer_code_final,
        CASE
            WHEN ((fs.customer_code)::text = 'UNKNOWN'::text) THEN 'Khách hàng chờ xác nhận'::character varying
            ELSE fs.customer_name
        END AS customer_name_final,
        CASE
            WHEN ((fs.customer_code)::text = 'UNKNOWN'::text) THEN 'NEEDS_REVIEW'::text
            ELSE 'MAPPED'::text
        END AS customer_mapping_status,
    COALESCE(ge.province_name_suggested, (fs.province_name)::text, 'Chưa xác định'::text) AS province_name_final,
    COALESCE(ge.region_suggested, (fs.region)::text, 'Chưa xác định'::text) AS region_final,
        CASE
            WHEN (fs.province_name IS NOT NULL) THEN 'MASTER_DATA'::text
            WHEN (ge.province_name_suggested IS NOT NULL) THEN ge.geo_mapping_status
            ELSE 'UNKNOWN_GEO'::text
        END AS geo_mapping_status,
    COALESCE(NULLIF(pcm.suggested_line_name, 'UNCLASSIFIED'::text), NULLIF((fs.line_name)::text, 'UNCLASSIFIED'::text), 'Chưa phân loại'::text) AS line_name_final,
    COALESCE(pcm.suggested_group_code, (fs.group_code)::text, 'UNCLASSIFIED'::text) AS group_code_final,
    COALESCE(NULLIF(pcm.suggested_group_name, 'UNCLASSIFIED'::text), NULLIF((fs.group_name)::text, 'UNCLASSIFIED'::text), 'Chưa phân loại'::text) AS group_name_final,
        CASE
            WHEN (pcm.product_code IS NOT NULL) THEN 'ENRICHED_APPROVED'::text
            WHEN ((upper((COALESCE(fs.group_code, 'UNCLASSIFIED'::character varying))::text) = 'UNCLASSIFIED'::text) OR (upper((COALESCE(fs.line_name, 'UNCLASSIFIED'::character varying))::text) = 'UNCLASSIFIED'::text)) THEN 'UNCLASSIFIED_REMAINING'::text
            ELSE 'MASTER_DATA'::text
        END AS product_classification_status,
    pcm.confidence_score AS product_classification_confidence,
    pcm.mapping_method AS product_classification_rule
   FROM ((tnbike.fact_sales fs
     LEFT JOIN tnbike.product_classification_map pcm ON ((((fs.product_code)::text = (pcm.product_code)::text) AND (pcm.review_status = ANY (ARRAY['AUTO_APPROVED'::text, 'MANUAL_APPROVED'::text])) AND (pcm.confidence_score >= 0.90))))
     LEFT JOIN tnbike.geo_enrichment_review ge ON ((((fs.so_number)::text = (ge.so_number)::text) AND (ge.confidence_score >= 0.90))));


--
-- Name: v_monthly_by_group; Type: VIEW; Schema: tnbike; Owner: -
--

CREATE VIEW tnbike.v_monthly_by_group AS
 SELECT fiscal_year,
    fiscal_month,
    group_code,
    group_name,
    count(DISTINCT so_number) AS order_count,
    sum(quantity) AS total_qty,
    sum(line_total) AS total_revenue,
    round(avg(unit_price), 0) AS avg_unit_price
   FROM tnbike.fact_sales
  GROUP BY fiscal_year, fiscal_month, group_code, group_name;


--
-- Name: VIEW v_monthly_by_group; Type: COMMENT; Schema: tnbike; Owner: -
--

COMMENT ON VIEW tnbike.v_monthly_by_group IS 'Doanh số tháng × nhóm SP cấp 1 — dùng cho trend analysis và seasonality';


--
-- Name: v_sku_monthly; Type: VIEW; Schema: tnbike; Owner: -
--

CREATE VIEW tnbike.v_sku_monthly AS
 SELECT fiscal_year,
    fiscal_month,
    product_code,
    product_name,
    color,
    line_name,
    group_code,
    sum(quantity) AS total_qty,
    sum(line_total) AS total_revenue,
    count(DISTINCT so_number) AS order_count
   FROM tnbike.fact_sales
  GROUP BY fiscal_year, fiscal_month, product_code, product_name, color, line_name, group_code;


--
-- Name: VIEW v_sku_monthly; Type: COMMENT; Schema: tnbike; Owner: -
--

COMMENT ON VIEW tnbike.v_sku_monthly IS 'Doanh số SKU × màu × tháng — dùng cho color/variant trend analysis';


